	getBargainList() {
		let limit = this.$config.LIMIT;
		getBargainList({
			page: 1,
			limit: this.numberConfig>=limit?limit:this.numberConfig
		}).then(res => {
			this.bargList = res.data
		})
	},
	bargDetail(item){
		// #ifndef MP
		this.$emit('changeBarg', item);
		// #endif
		// #ifdef MP
		openBargainSubscribe().then(res=>{
		   this.$emit('changeBarg', item);
		})
		// #endif
	}

